// =========================================================================

const INCLUIR_PROVENTOS  = true;   // false = só posições em custódia
const EMITIR_DIAGNOSTICO = false;   // acrescenta 1 item com o que não foi lido

const fileName = $('Webhook').item.json.body.fileName || '';
const submittedAt = null;

const meses = {
