  outubro:'10', novembro:'11', dezembro:'12'
};

// Só cosmético: renomeia a categoria na saída. Sigla desconhecida passa direto.
const APELIDOS = { DEB: 'Debêntures', FII: 'FII', ETF: 'ETF' };

function num(v) {
  if (v === undefined || v === null) return 0;
  const s = String(v).trim();
  if (s === '' || s === '-') return 0;
  const n = parseFloat(s.replace(/\./g, '').replace(',', '.'));
