const avisos = [];

// =========================================================================
// 1. DESCOBERTA DAS SEÇÕES
// Todo título é "Posição - <sigla>[ - <descrição>]" seguido do cabeçalho,
// que sempre começa em "Produto". Nada é listado a priori.
// =========================================================================

// Vocabulário de rótulos de coluna. Serve só pra saber onde o cabeçalho
// termina e os dados começam. Rótulo novo = sobra uma palavra solta antes
// da primeira linha, o que é inofensivo (nenhum regex de dado casa com ela).
const ROTULOS = new Set([
  'produto','tipo','instituição','instituicao','vencimento','quantidade',
  'preço','preco','unitário','unitario','atualizado','atualizada','de','do','da',
  'fechamento','valor','aplicado','líquido','liquido','pagamento','evento',
  'emissor','data','código','codigo','isin','taxa','indexador','corretora',
  'conta','escriturador','nome','ativo','bruto','saldo','descrição','descricao','e'
]);

const soLetras = t => t.toLowerCase().replace(/[^a-zà-ÿ]/g, '');

// Consome o cabeçalho a partir de "Produto"; devolve onde os dados começam
// e a lista de rótulos encontrados (usada pra classificar o layout).
function leCabecalho(texto, posProduto) {
  const rotulos = [];
  let i = posProduto;
  while (i < texto.length) {
    const resto = texto.slice(i);
    const m = resto.match(/^\s*(\S+)/);
    if (!m) break;
    const palavra = soLetras(m[1]);
    if (!ROTULOS.has(palavra)) break;
    rotulos.push(palavra);
    i += m[0].length;
  }
  return { fim: i, rotulos };
}

// Localiza todos os títulos "Posição - ..." e onde cada tabela começa
const titulos = [];
{
  const re = /Posição\s*-\s*(.+?)\s+(?=Produto\b)/g;
  let m;
  while ((m = re.exec(clean)) !== null) {
    const bruto = m[1].replace(/\s+/g, ' ').trim();
    const sigla = bruto.split(/\s+-\s+/)[0].trim();
    const cab = leCabecalho(clean, m.index + m[0].length);
    titulos.push({ sigla, inicio: m.index, dados: cab.fim, rotulos: cab.rotulos });
  }
}

// Seções que não usam o prefixo "Posição"
const OUTRAS = [
  { chave: 'PROVENTOS',  re: /Proventos\s+recebidos/i },
  { chave: 'REEMBOLSOS', re: /Reembolsos/i },
  { chave: 'NEGOCIACAO', re: /Negociação/i },
  { chave: 'RESUMO',     re: /Resumo\s+dos\s+negócios/i }
];
for (const o of OUTRAS) {
  const idx = clean.search(o.re);
  if (idx === -1) continue;
  const pProd = clean.indexOf('Produto', idx);
  const cab = (pProd !== -1 && pProd - idx < 400)
    ? leCabecalho(clean, pProd + 'Produto'.length)
    : { fim: idx, rotulos: [] };
  titulos.push({ sigla: o.chave, inicio: idx, dados: cab.fim, rotulos: cab.rotulos });
}

titulos.sort((a, b) => a.inicio - b.inicio);

// Agrupa repetições do mesmo título (o cabeçalho se repete a cada página)
// e recorta o bloco de cada seção até o próximo título DIFERENTE.
const secoes = [];
for (let i = 0; i < titulos.length; i++) {
  const t = titulos[i];
  if (secoes.length && secoes[secoes.length - 1].sigla === t.sigla) {
    // mesma seção, outra página: remove o cabeçalho repetido
    secoes[secoes.length - 1].cortes.push([t.inicio, t.dados]);
    continue;
  }
  secoes.push({ sigla: t.sigla, rotulos: t.rotulos, inicio: t.dados,
                fimTitulo: t.inicio, cortes: [] });
}
for (let i = 0; i < secoes.length; i++) {
  const proximo = titulos.find(t => t.inicio > secoes[i].fimTitulo && t.sigla !== secoes[i].sigla);
  secoes[i].fim = proximo ? proximo.inicio : clean.length;
  // texto da seção com os cabeçalhos das páginas seguintes removidos
  let txt = clean.slice(secoes[i].inicio, secoes[i].fim);
  for (const [a, b] of secoes[i].cortes) {
    if (a >= secoes[i].inicio && b <= secoes[i].fim) {
      txt = txt.replace(clean.slice(a, b), ' ');
    }
  }
  secoes[i].texto = txt;
}

// Classifica o layout pelo cabeçalho, não pelo nome da seção
function layoutDe(sec) {
  const r = sec.rotulos;
  if (sec.sigla === 'PROVENTOS') return 'PROVENTOS';
  if (r.includes('aplicado')) return 'TESOURO';
  if (r.includes('vencimento')) return 'RENDA_FIXA';
  if (r.includes('tipo')) return 'RENDA_VARIAVEL';
  return null;
}

// =========================================================================
// 2. DICIONÁRIO DE INSTITUIÇÕES (aprendido do próprio documento)
// =========================================================================
const dicInst = new Map();
const espacos = s => (s.match(/ /g) || []).length;

// Chave de comparação: só letras e números. Assim "XP ... S/A" e "XP ... S/A."
// (com ponto final, como sai no Tesouro) viram a mesma instituição.
const chaveDe = s => s.toUpperCase().replace(/[^0-9A-ZÀ-Ü]/g, '');

function registraInst(nome) {
  if (!nome) return;
  const limpo = nome.replace(/\s+/g, ' ').trim();
  if (limpo.length < 6) return;
  const chave = chaveDe(limpo);
  const atual = dicInst.get(chave);
  if (!atual || espacos(limpo) > espacos(atual)) dicInst.set(chave, limpo);
}

function canonInst(nome) {
  if (!nome) return nome;
  return dicInst.get(chaveDe(nome)) || nome.replace(/\s+/g, ' ').trim();
}

// Mesmo tratamento para os tipos de evento dos proventos: o PDF cola palavras
// ("Juros SobreCapital Próprio"), o que criaria dois eventos distintos no banco.
const dicEvento = new Map();

function registraEvento(nome) {
  if (!nome) return;
  const limpo = nome.replace(/\s+/g, ' ').trim();
  if (limpo.length < 3) return;
  const chave = chaveDe(limpo);
  const atual = dicEvento.get(chave);
  if (!atual || espacos(limpo) > espacos(atual)) dicEvento.set(chave, limpo);
}

function canonEvento(nome) {
  if (!nome) return nome;
  return dicEvento.get(chaveDe(nome)) || nome.replace(/\s+/g, ' ').trim();
}

// Corta do fim do bloco a maior instituição conhecida que seja sufixo dele
function cortaInstConhecida(bloco) {
  const semEspaco = chaveDe(bloco);
  let melhor = null;
  for (const [chave, grafia] of dicInst) {
    if (semEspaco.endsWith(chave) && (!melhor || chave.length > melhor.chave.length)) {
      melhor = { chave, grafia };
    }
  }
  if (!melhor) return null;
  let restantes = melhor.chave.length, corte = bloco.length;
  for (let i = bloco.length - 1; i >= 0 && restantes > 0; i--) {
    if (chaveDe(bloco[i])) restantes--;
    corte = i;
  }
  return { nome: bloco.slice(0, corte).trim(), inst: melhor.grafia };
}

// Fallback só pra renda fixa quando o dicionário ainda está vazio
function splitInstHeuristico(bloco) {
  const b = bloco.replace(/\s+/g, ' ').trim();
  const mBroker = b.match(/(\S+(?:\s+\S+)*?\s+(?:CTVM|CCTVM|CVMC|DTVM)(?:\s+S\/?A\.?)?)\s*$/i);
  if (mBroker) {
    const inst = mBroker[1].trim();
    const nome = b.slice(0, b.length - mBroker[0].length).trim();
    return { nome: nome || inst, inst };
  }
  const tk = b.split(' ');
  if (tk.length % 2 === 0) {
    const h1 = tk.slice(0, tk.length / 2).join(' ');
    const h2 = tk.slice(tk.length / 2).join(' ');
    if (h1 === h2) return { nome: h1, inst: h2 };
  }
  const mSA = b.match(/^(.+?S\/?A\.?)\s+(.+S\/?A\.?)$/i);
  if (mSA) return { nome: mSA[1].trim(), inst: mSA[2].trim() };
  return { nome: b, inst: '' };   // campo vazio é melhor que campo errado
}

// =========================================================================
// 3. PARSERS POR LAYOUT
// =========================================================================

// Tipos de papel: conjunto fechado definido pela B3. Se vier um tipo novo,
// o splitMeio devolve tipo vazio e a instituição sai pelo dicionário.
const TIPO_RE = /(?:^|\s)((?:RF\s+)?(?:Internacional|Cotas|Direito|Direitos|Recibo|Subscrição|Fração|Fundo|Ações|BDR|DRN|ETF|UNIT|UNT|ON|PN[ABCD]?|CI))(?=\s)/g;

function splitMeio(meio) {
  let achado = null, m;
  TIPO_RE.lastIndex = 0;
  while ((m = TIPO_RE.exec(meio)) !== null) {   // fica com a ÚLTIMA ocorrência
    const resto = meio.slice(m.index + m[0].length).trim();
    if (resto) achado = {
      nome: meio.slice(0, m.index).trim(),
      tipo: m[1].replace(/\s+/g, ' '),
      inst: resto
    };
  }
  if (achado) return achado;
  const porDic = cortaInstConhecida(meio);          // tipo desconhecido:
  if (porDic) return { ...porDic, tipo: '' };       // salva pelo dicionário
  return { nome: meio.trim(), tipo: '', inst: '' };
}

const LINHA_RV   = /([A-Z][A-Z0-9]{2,7})\s*-\s*(.+?)\s+([\d.,]+)\s+R\$\s*([\d.,]+)\s+R\$\s*([\d.,]+)/g;
const LINHA_RF   = /(.+?)\s+(\d{2}\/\d{2}\/\d{4})\s+([\d.,]+)\s+R\$\s*([\d.,]+)\s+R\$\s*([\d.,]+)/g;
const LINHA_PROV = /([A-Z][A-Z0-9]{2,7})\s*-\s*(.+?)\s+(\d{2}\/\d{2}\/\d{4})\s+(.+?)\s+([\d.,]+)\s+R\$\s*([\d.,]+)\s+R\$\s*([\d.,]+)/g;

function parseRV(sec, categoria) {
  const out = [];
  let m; LINHA_RV.lastIndex = 0;
  while ((m = LINHA_RV.exec(sec.texto)) !== null) {
    const s = splitMeio(m[2]);
    registraInst(s.inst);
    out.push({
      ticker: m[1].toUpperCase(), nome_ativo: s.nome, tipo_ativo: s.tipo,
      instituicao: s.inst, categoria,
      quantidade: num(m[3]), preco_fechamento: num(m[4]), valor_atualizado: num(m[5]),
      tipo_registro: 'Posição Custódia'
    });
  }
  return out;
}

function parseRF(sec, categoria) {
  const out = [];
  const prefixo = new RegExp('^' + sec.sigla.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*-\\s*', 'i');
  let m; LINHA_RF.lastIndex = 0;
  while ((m = LINHA_RF.exec(sec.texto)) !== null) {
    const bloco = m[1].replace(/\s+/g, ' ').trim().replace(prefixo, '').trim();
    const achado = cortaInstConhecida(bloco) || splitInstHeuristico(bloco);
    registraInst(achado.inst);
    out.push({
      ticker: sec.sigla,
      nome_ativo: (sec.sigla + ' - ' + achado.nome).replace(/\s+/g, ' ').trim(),
      tipo_ativo: 'Renda Fixa', instituicao: achado.inst, categoria,
      quantidade: num(m[3]), preco_fechamento: num(m[4]), valor_atualizado: num(m[5]),
      tipo_registro: 'Posição Custódia', vencimento: m[2]
    });
  }
  return out;
}

function parseTesouro(sec, categoria) {
  const out = [];
  const blocos = sec.texto.split(/(?=Tesouro\s)/i).filter(b => /^Tesouro\s/i.test(b));
  for (const bloco of blocos) {
    const vals = bloco.match(/(\d{2}\/\d{2}\/\d{4})\s+([\d.,]+)\s+R\$\s*([\d.,]+)\s+R\$\s*([\d.,]+)/);
    if (!vals) continue;
    const resto = bloco.slice(0, bloco.indexOf(vals[0])).replace(/\s+/g, ' ').trim();
    let nomeAtivo = resto, inst = '';
    const mNome = resto.match(/^(Tesouro\s+.*?\b\d{4}\b)\s*(.*)$/i);   // nome termina no ano
    if (mNome) { nomeAtivo = mNome[1].trim(); inst = mNome[2].trim(); }
    registraInst(inst);
    out.push({
      ticker: nomeAtivo, nome_ativo: nomeAtivo, tipo_ativo: 'Título Público',
      instituicao: inst, categoria,
      quantidade: num(vals[2]), preco_fechamento: num(vals[3]),
      valor_atualizado: num(vals[4]), tipo_registro: 'Posição Custódia',
      vencimento: vals[1]
    });
  }
  return out;
}

function parseProventos(sec) {
  const out = [];
  let m; LINHA_PROV.lastIndex = 0;
  while ((m = LINHA_PROV.exec(sec.texto)) !== null) {
    // m[4] = "<tipo de evento> <instituição>". Sem lista de eventos:
    // corta a instituição pelo dicionário, o que sobra é o evento.
    const meio = m[4].replace(/\s+/g, ' ').trim();
    const corte = cortaInstConhecida(meio);
    const evento = corte ? corte.nome : meio;
    const inst   = corte ? corte.inst : '';
    if (!corte) avisos.push(`provento de ${m[1]}: instituição não identificada`);
    registraEvento(evento);
    out.push({
      ticker: m[1].toUpperCase(), nome_ativo: m[2].trim(),
      tipo_ativo: evento, instituicao: inst, categoria: 'Proventos',
      quantidade: num(m[5]), preco_fechamento: num(m[6]),
      valor_atualizado: num(m[7]), tipo_registro: 'Provento',
      data_pagamento: m[3]
    });
  }
  return out;
}

// =========================================================================
// 4. EXECUÇÃO — posições primeiro (alimentam o dicionário), proventos depois
// =========================================================================
const posRV = [], posRF = [], posTD = [];
const pendentesRF = [];

for (const sec of secoes) {
  const layout = layoutDe(sec);
  const categoria = APELIDOS[sec.sigla] || sec.sigla;

  if (layout === 'RENDA_VARIAVEL')      posRV.push(...parseRV(sec, categoria));
  else if (layout === 'TESOURO')        posTD.push(...parseTesouro(sec, categoria));
  else if (layout === 'RENDA_FIXA')     pendentesRF.push({ sec, categoria });
  else if (layout === 'PROVENTOS')      { /* depois */ }
  else if (['REEMBOLSOS','NEGOCIACAO','RESUMO'].includes(sec.sigla)) {
    if (!/não\s+possui\s+dados/i.test(sec.texto)) {
      avisos.push(`seção "${sec.sigla}" tem dados mas não é lida por este script`);
    }
  } else {
    avisos.push(`seção "${sec.sigla}" ignorada: layout não reconhecido (colunas: ${sec.rotulos.join(', ') || 'nenhuma'})`);
  }
}

// renda fixa depois de toda a RV, pra o dicionário já estar montado
for (const p of pendentesRF) posRF.push(...parseRF(p.sec, p.categoria));

let proventos = [];
if (INCLUIR_PROVENTOS) {
  const secProv = secoes.find(s => s.sigla === 'PROVENTOS');
  if (secProv) proventos = parseProventos(secProv);
}

for (const r of [...posRV, ...posRF, ...posTD]) {
  if (!r.instituicao) avisos.push(`${r.ticker}: instituição não identificada`);
}

// =========================================================================
// 5. SAÍDA
// =========================================================================
const rows = [...posRV, ...posRF, ...posTD, ...proventos];

const saida = rows.map(r => ({
  json: {
    ...r,
    instituicao: canonInst(r.instituicao),
    tipo_ativo: r.tipo_registro === 'Provento' ? canonEvento(r.tipo_ativo) : r.tipo_ativo,
    data_referencia: dataReferencia,
    submitted_at: submittedAt
  }
}));

if (avisos.length) console.warn('[B3 parser]', avisos.join(' | '));

if (EMITIR_DIAGNOSTICO) {
  saida.push({ json: {
    tipo_registro: 'Diagnóstico',
    data_referencia: dataReferencia,
    secoes_encontradas: secoes.map(s => `${s.sigla}:${layoutDe(s) || 'DESCONHECIDO'}`),
    linhas_extraidas: rows.length,
    instituicoes: [...dicInst.values()],
    avisos
  }});
}

return saida;

